1	use std::ops::Deref;
2	
3	use typst_library::diag::SourceResult;
4	use typst_library::engine::Engine;
5	use typst_library::layout::grid::resolve::{Footer, Header, Repeatable};
6	use typst_library::layout::{Abs, Axes, Frame, Regions};
7	
8	use super::layouter::{FinishedHeaderRowInfo, GridLayouter, RowState};
9	use super::rowspans::UnbreakableRowGroup;
10	
11	impl<'a> GridLayouter<'a> {
12	    /// Checks whether a region break could help a situation where we're out of
13	    /// space for the next row. The criteria are:
14	    ///
15	    /// 1. If we could progress at the top of the region, that indicates the
16	    ///    region has a backlog, or (if we're at the first region) a region break
17	    ///    is at all possible (`regions.last` is `Some()`), so that's sufficient.
18	    ///
19	    /// 2. Otherwise, we may progress if another region break is possible
20	    ///    (`regions.last` is still `Some()`) and non-repeating rows have been
21	    ///    placed, since that means the space they occupy will be available in the
22	    ///    next region.
23	    #[inline]
24	    pub fn may_progress_with_repeats(&self) -> bool {
25	        // TODO(subfooters): check below isn't enough to detect non-repeating
26	        // footers... we can also change 'initial_after_repeats' to stop being
27	        // calculated if there were any non-repeating footers.
28	        self.current.could_progress_at_top
29	            || self.regions.last.is_some()
30	                && self.regions.size.y != self.current.initial_after_repeats
31	    }
32	
33	    pub fn place_new_headers(
34	        &mut self,
35	        consecutive_header_count: &mut usize,
36	        engine: &mut Engine,
37	    ) -> SourceResult<()> {
38	        *consecutive_header_count += 1;
39	        let (consecutive_headers, new_upcoming_headers) =
40	            self.upcoming_headers.split_at(*consecutive_header_count);
41	
42	        if new_upcoming_headers.first().is_some_and(|next_header| {
43	            consecutive_headers.last().is_none_or(|latest_header| {
44	                !latest_header.short_lived
45	                    && next_header.range.start == latest_header.range.end
46	            }) && !next_header.short_lived
47	        }) {
48	            // More headers coming, so wait until we reach them.
49	            return Ok(());
50	        }
51	
52	        self.upcoming_headers = new_upcoming_headers;
53	        *consecutive_header_count = 0;
54	
55	        let [first_header, ..] = consecutive_headers else {
56	            self.flush_orphans();
57	            return Ok(());
58	        };
59	
60	        // Assuming non-conflicting headers sorted by increasing y, this must
61	        // be the header with the lowest level (sorted by increasing levels).
62	        let first_level = first_header.level;
63	
64	        // Stop repeating conflicting headers, even if the new headers are
65	        // short-lived or won't repeat.
66	        //
67	        // If we go to a new region before the new headers fit alongside their
68	        // children (or in general, for short-lived), the old headers should
69	        // not be displayed anymore.
70	        let first_conflicting_pos =
71	            self.repeating_headers.partition_point(|h| h.level < first_level);
72	        self.repeating_headers.truncate(first_conflicting_pos);
73	
74	        // Ensure upcoming rows won't see that these headers will occupy any
75	        // space in future regions anymore.
76	        for removed_height in
77	            self.current.repeating_header_heights.drain(first_conflicting_pos..)
78	        {
79	            self.current.repeating_header_height -= removed_height;
80	        }
81	
82	        // Layout short-lived headers immediately.
83	        if consecutive_headers.last().is_some_and(|h| h.short_lived) {
84	            // No chance of orphans as we're immediately placing conflicting
85	            // headers afterwards, which basically are not headers, for all intents
86	            // and purposes. It is therefore guaranteed that all new headers have
87	            // been placed at least once.
88	            self.flush_orphans();
89	
90	            // Layout each conflicting header independently, without orphan
91	            // prevention (as they don't go into 'pending_headers').
92	            // These headers are short-lived as they are immediately followed by a
93	            // header of the same or lower level, such that they never actually get
94	            // to repeat.
95	            self.layout_new_headers(consecutive_headers, true, engine)?;
96	        } else {
97	            // Let's try to place pending headers at least once.
98	            // This might be a waste as we could generate an orphan and thus have
99	            // to try to place old and new headers all over again, but that happens
100	            // for every new region anyway, so it's rather unavoidable.
101	            let snapshot_created =
102	                self.layout_new_headers(consecutive_headers, false, engine)?;
103	
104	            // Queue the new headers for layout. They will remain in this
105	            // vector due to orphan prevention.
106	            //
107	            // After the first subsequent row is laid out, move to repeating, as
108	            // it's then confirmed the headers won't be moved due to orphan
109	            // prevention anymore.
110	            self.pending_headers = consecutive_headers;
111	
112	            if !snapshot_created {
113	                // Region probably couldn't progress.
114	                //
115	                // Mark new pending headers as final and ensure there isn't a
116	                // snapshot.
117	                self.flush_orphans();
118	            }
119	        }
120	
121	        Ok(())
122	    }
123	
124	    /// Lays out rows belonging to a header, returning the calculated header
125	    /// height only for that header. Indicates to the laid out rows that they
126	    /// should inform their laid out heights if appropriate (auto or fixed
127	    /// size rows only).
128	    #[inline]
129	    fn layout_header_rows(
130	        &mut self,
131	        header: &Header,
132	        engine: &mut Engine,
133	        disambiguator: usize,
134	        as_short_lived: bool,
135	        is_being_repeated: bool,
136	    ) -> SourceResult<Abs> {
137	        let mut header_height = Abs::zero();
138	        for y in header.range.clone() {
139	            header_height += self
140	                .layout_row_with_state(
141	                    y,
142	                    engine,
143	                    disambiguator,
144	                    RowState {
145	                        current_row_height: Some(Abs::zero()),
146	                        in_active_repeatable: !as_short_lived,
147	                        is_being_repeated,
148	                    },
149	                )?
150	                .current_row_height
151	                .unwrap_or_default();
152	        }
153	        Ok(header_height)
154	    }
155	
156	    /// This function should be called each time an additional row has been
157	    /// laid out in a region to indicate that orphan prevention has succeeded.
158	    ///
159	    /// It removes the current orphan snapshot and flushes pending headers,
160	    /// such that a non-repeating header won't try to be laid out again
161	    /// anymore, and a repeating header will begin to be part of
162	    /// `repeating_headers`.
163	    pub fn flush_orphans(&mut self) {
164	        self.current.lrows_orphan_snapshot = None;
165	        self.flush_pending_headers();
166	    }
167	
168	    /// Indicates all currently pending headers have been successfully placed
169	    /// once, since another row has been placed after them, so they are
170	    /// certainly not orphans.
171	    pub fn flush_pending_headers(&mut self) {
172	        if self.pending_headers.is_empty() {
173	            return;
174	        }
175	
176	        for header in self.pending_headers {
177	            if header.repeated {
178	                // Vector remains sorted by increasing levels:
179	                // - 'pending_headers' themselves are sorted, since we only
180	                // push non-mutually-conflicting headers at a time.
181	                // - Before pushing new pending headers in
182	                // 'layout_new_pending_headers', we truncate repeating headers
183	                // to remove anything with the same or higher levels as the
184	                // first pending header.
185	                // - Assuming it was sorted before, that truncation only keeps
186	                // elements with a lower level.
187	                // - Therefore, by pushing this header to the end, it will have
188	                // a level larger than all the previous headers, and is thus
189	                // in its 'correct' position.
190	                self.repeating_headers.push(header);
191	            }
192	        }
193	
194	        self.pending_headers = Default::default();
195	    }
196	
197	    /// Lays out the rows of repeating and pending headers at the top of the
198	    /// region.
199	    ///
200	    /// Assumes the footer height for the current region has already been
201	    /// calculated. Skips regions as necessary to fit all headers and all
202	    /// footers.
203	    pub fn layout_active_headers(&mut self, engine: &mut Engine) -> SourceResult<()> {
204	        // Generate different locations for content in headers across its
205	        // repetitions by assigning a unique number for each one.
206	        let disambiguator = self.finished.len();
207	
208	        let header_height = self.simulate_header_height(
209	            self.repeating_headers
210	                .iter()
211	                .copied()
212	                .chain(self.pending_headers.iter().map(Repeatable::deref)),
213	            &self.regions,
214	            engine,
215	            disambiguator,
216	        )?;
217	
218	        // We already take the footer into account below.
219	        // While skipping regions, footer height won't be automatically
220	        // re-calculated until the end.
221	        let mut skipped_region = false;
222	        while self.unbreakable_rows_left == 0
223	            && !self.regions.size.y.fits(header_height)
224	            && self.may_progress_with_repeats()
225	        {
226	            // Advance regions without any output until we can place the
227	            // header and the footer.
228	            self.finish_region_internal(
229	                Frame::soft(Axes::splat(Abs::zero())),
230	                vec![],
231	                FinishedHeaderRowInfo::default(),
232	            );
233	
234	            // TODO(layout model): re-calculate heights of headers and footers
235	            // on each region if 'full' changes? (Assuming height doesn't
236	            // change for now...)
237	            //
238	            // Would remove the footer height update below (move it here).
239	            skipped_region = true;
240	
241	            self.regions.size.y -= self.current.footer_height;
242	            self.current.initial_after_repeats = self.regions.size.y;
243	        }
244	
245	        if let Some(footer) = &self.grid.footer
246	            && footer.repeated
247	            && skipped_region
248	        {
249	            // Simulate the footer again; the region's 'full' might have
250	            // changed.
251	            self.regions.size.y += self.current.footer_height;
252	            self.current.footer_height = self
253	                .simulate_footer(footer, &self.regions, engine, disambiguator)?
254	                .height;
255	            self.regions.size.y -= self.current.footer_height;
256	        }
257	
258	        let repeating_header_rows =
259	            total_header_row_count(self.repeating_headers.iter().copied());
260	
261	        let pending_header_rows =
262	            total_header_row_count(self.pending_headers.iter().map(Repeatable::deref));
263	
264	        // Group of headers is unbreakable.
265	        // Thus, no risk of 'finish_region' being recursively called from
266	        // within 'layout_row'.
267	        self.unbreakable_rows_left += repeating_header_rows + pending_header_rows;
268	
269	        self.current.last_repeated_header_end =
270	            self.repeating_headers.last().map(|h| h.range.end).unwrap_or_default();
271	
272	        // Reset the header height for this region.
273	        // It will be re-calculated when laying out each header row.
274	        self.current.repeating_header_height = Abs::zero();
275	        self.current.repeating_header_heights.clear();
276	
277	        debug_assert!(self.current.lrows.is_empty());
278	        debug_assert!(self.current.lrows_orphan_snapshot.is_none());
279	        let may_progress = self.may_progress_with_repeats();
280	
281	        if may_progress {
282	            // Enable orphan prevention for headers at the top of the region.
283	            // Otherwise, we will flush pending headers below, after laying
284	            // them out.
285	            //
286	            // It is very rare for this to make a difference as we're usually
287	            // at the 'last' region after the first skip, at which the snapshot
288	            // is handled by 'layout_new_headers'. Either way, we keep this
289	            // here for correctness.
290	            self.current.lrows_orphan_snapshot = Some(self.current.lrows.len());
291	        }
292	
293	        // Use indices to avoid double borrow. We don't mutate headers in
294	        // 'layout_row' so this is fine.
295	        let mut i = 0;
296	        while let Some(&header) = self.repeating_headers.get(i) {
297	            let header_height =
298	                self.layout_header_rows(header, engine, disambiguator, false, true)?;
299	            self.current.repeating_header_height += header_height;
300	
301	            // We assume that this vector will be sorted according
302	            // to increasing levels like 'repeating_headers' and
303	            // 'pending_headers' - and, in particular, their union, as this
304	            // vector is pushed repeating heights from both.
305	            //
306	            // This is guaranteed by:
307	            // 1. We always push pending headers after repeating headers,
308	            // as we assume they don't conflict because we remove
309	            // conflicting repeating headers when pushing a new pending
310	            // header.
311	            //
312	            // 2. We push in the same order as each.
313	            //
314	            // 3. This vector is also modified when pushing a new pending
315	            // header, where we remove heights for conflicting repeating
316	            // headers which have now stopped repeating. They are always at
317	            // the end and new pending headers respect the existing sort,
318	            // so the vector will remain sorted.
319	            self.current.repeating_header_heights.push(header_height);
320	
321	            i += 1;
322	        }
323	
324	        self.current.repeated_header_rows = self.current.lrows.len();
325	        self.current.initial_after_repeats = self.regions.size.y;
326	
327	        let mut has_non_repeated_pending_header = false;
328	        for header in self.pending_headers {
329	            if !header.repeated {
330	                self.current.initial_after_repeats = self.regions.size.y;
331	                has_non_repeated_pending_header = true;
332	            }
333	            let header_height =
334	                self.layout_header_rows(header, engine, disambiguator, false, false)?;
335	            if header.repeated {
336	                self.current.repeating_header_height += header_height;
337	                self.current.repeating_header_heights.push(header_height);
338	            }
339	        }
340	
341	        if !has_non_repeated_pending_header {
342	            self.current.initial_after_repeats = self.regions.size.y;
343	        }
344	
345	        if !may_progress {
346	            // Flush pending headers immediately, as placing them again later
347	            // won't help.
348	            self.flush_orphans();
349	        }
350	
351	        Ok(())
352	    }
353	
354	    /// Lays out headers found for the first time during row layout.
355	    ///
356	    /// If `short_lived` is true, these headers are immediately followed by
357	    /// a conflicting header, so it is assumed they will not be pushed to
358	    /// pending headers.
359	    ///
360	    /// Returns whether orphan prevention was successfully setup, or couldn't
361	    /// due to short-lived headers or the region couldn't progress.
362	    pub fn layout_new_headers(
363	        &mut self,
364	        headers: &'a [Repeatable<Header>],
365	        short_lived: bool,
366	        engine: &mut Engine,
367	    ) -> SourceResult<bool> {
368	        // At first, only consider the height of the given headers. However,
369	        // for upcoming regions, we will have to consider repeating headers as
370	        // well.
371	        let header_height = self.simulate_header_height(
372	            headers.iter().map(Repeatable::deref),
373	            &self.regions,
374	            engine,
375	            0,
376	        )?;
377	
378	        while self.unbreakable_rows_left == 0
379	            && !self.regions.size.y.fits(header_height)
380	            && self.may_progress_with_repeats()
381	        {
382	            // Note that, after the first region skip, the new headers will go
383	            // at the top of the region, but after the repeating headers that
384	            // remained (which will be automatically placed in 'finish_region').
385	            self.finish_region(engine, false)?;
386	        }
387	
388	        // Remove new headers at the end of the region if the upcoming row
389	        // doesn't fit.
390	        // TODO(subfooters): what if there is a footer right after it?
391	        let should_snapshot = !short_lived
392	            && self.current.lrows_orphan_snapshot.is_none()
393	            && self.may_progress_with_repeats();
394	
395	        if should_snapshot {
396	            // If we don't enter this branch while laying out non-short lived
397	            // headers, that means we will have to immediately flush pending
398	            // headers and mark them as final, since trying to place them in
399	            // the next page won't help get more space.
400	            self.current.lrows_orphan_snapshot = Some(self.current.lrows.len());
401	        }
402	
403	        let mut at_top = self.regions.size.y == self.current.initial_after_repeats;
404	
405	        self.unbreakable_rows_left +=
406	            total_header_row_count(headers.iter().map(Repeatable::deref));
407	
408	        for header in headers {
409	            let header_height =
410	                self.layout_header_rows(header, engine, 0, false, false)?;
411	
412	            // Only store this header height if it is actually going to
413	            // become a pending header. Otherwise, pretend it's not a
414	            // header... This is fine for consumers of 'header_height' as
415	            // it is guaranteed this header won't appear in a future
416	            // region, so multi-page rows and cells can effectively ignore
417	            // this header.
418	            if !short_lived && header.repeated {
419	                self.current.repeating_header_height += header_height;
420	                self.current.repeating_header_heights.push(header_height);
421	                if at_top {
422	                    self.current.initial_after_repeats = self.regions.size.y;
423	                }
424	            } else {
425	                at_top = false;
426	            }
427	        }
428	
429	        Ok(should_snapshot)
430	    }
431	
432	    /// Calculates the total expected height of several headers.
433	    pub fn simulate_header_height<'h: 'a>(
434	        &self,
435	        headers: impl IntoIterator<Item = &'h Header>,
436	        regions: &Regions<'_>,
437	        engine: &mut Engine,
438	        disambiguator: usize,
439	    ) -> SourceResult<Abs> {
440	        let mut height = Abs::zero();
441	        for header in headers {
442	            height +=
443	                self.simulate_header(header, regions, engine, disambiguator)?.height;
444	        }
445	        Ok(height)
446	    }
447	
448	    /// Simulate the header's group of rows.
449	    pub fn simulate_header(
450	        &self,
451	        header: &Header,
452	        regions: &Regions<'_>,
453	        engine: &mut Engine,
454	        disambiguator: usize,
455	    ) -> SourceResult<UnbreakableRowGroup> {
456	        // Note that we assume the invariant that any rowspan in a header is
457	        // fully contained within that header. Therefore, there won't be any
458	        // unbreakable rowspans exceeding the header's rows, and we can safely
459	        // assume that the amount of unbreakable rows following the first row
460	        // in the header will be precisely the rows in the header.
461	        self.simulate_unbreakable_row_group(
462	            header.range.start,
463	            Some(header.range.end - header.range.start),
464	            regions,
465	            engine,
466	            disambiguator,
467	        )
468	    }
469	
470	    /// Updates `self.footer_height` by simulating the footer, and skips to fitting region.
471	    pub fn prepare_footer(
472	        &mut self,
473	        footer: &Footer,
474	        engine: &mut Engine,
475	        disambiguator: usize,
476	    ) -> SourceResult<()> {
477	        let footer_height = self
478	            .simulate_footer(footer, &self.regions, engine, disambiguator)?
479	            .height;
480	        let mut skipped_region = false;
481	        while self.unbreakable_rows_left == 0
482	            && !self.regions.size.y.fits(footer_height)
483	            && self.regions.may_progress()
484	        {
485	            // Advance regions without any output until we can place the
486	            // footer.
487	            self.finish_region_internal(
488	                Frame::soft(Axes::splat(Abs::zero())),
489	                vec![],
490	                FinishedHeaderRowInfo::default(),
491	            );
492	            skipped_region = true;
493	        }
494	
495	        // TODO(subfooters): Consider resetting header height etc. if we skip
496	        // region. (Maybe move that step to `finish_region_internal`.)
497	        //
498	        // That is unnecessary at the moment as 'prepare_footers' is only
499	        // called at the start of the region, so header height is always zero
500	        // and no headers were placed so far, but what about when we can have
501	        // footers in the middle of the region? Let's think about this then.
502	        self.current.footer_height = if skipped_region {
503	            // Simulate the footer again; the region's 'full' might have
504	            // changed.
505	            self.simulate_footer(footer, &self.regions, engine, disambiguator)?
506	                .height
507	        } else {
508	            footer_height
509	        };
510	
511	        Ok(())
512	    }
513	
514	    /// Lays out all rows in the footer.
515	    /// They are unbreakable.
516	    pub fn layout_footer(
517	        &mut self,
518	        footer: &Footer,
519	        engine: &mut Engine,
520	        disambiguator: usize,
521	        is_being_repeated: bool,
522	    ) -> SourceResult<()> {
523	        // Ensure footer rows have their own height available.
524	        // Won't change much as we're creating an unbreakable row group
525	        // anyway, so this is mostly for correctness.
526	        self.regions.size.y += self.current.footer_height;
527	
528	        let repeats = self.grid.footer.as_ref().is_some_and(|f| f.repeated);
529	        let footer_len = self.grid.rows.len() - footer.start;
530	        self.unbreakable_rows_left += footer_len;
531	
532	        for y in footer.start..self.grid.rows.len() {
533	            self.layout_row_with_state(
534	                y,
535	                engine,
536	                disambiguator,
537	                RowState {
538	                    in_active_repeatable: repeats,
539	                    is_being_repeated,
540	                    ..Default::default()
541	                },
542	            )?;
543	        }
544	
545	        Ok(())
546	    }
547	
548	    // Simulate the footer's group of rows.
549	    pub fn simulate_footer(
550	        &self,
551	        footer: &Footer,
552	        regions: &Regions<'_>,
553	        engine: &mut Engine,
554	        disambiguator: usize,
555	    ) -> SourceResult<UnbreakableRowGroup> {
556	        // Note that we assume the invariant that any rowspan in a footer is
557	        // fully contained within that footer. Therefore, there won't be any
558	        // unbreakable rowspans exceeding the footer's rows, and we can safely
559	        // assume that the amount of unbreakable rows following the first row
560	        // in the footer will be precisely the rows in the footer.
561	        self.simulate_unbreakable_row_group(
562	            footer.start,
563	            Some(footer.end - footer.start),
564	            regions,
565	            engine,
566	            disambiguator,
567	        )
568	    }
569	}
570	
571	/// The total amount of rows in the given list of headers.
572	#[inline]
573	pub fn total_header_row_count<'h>(
574	    headers: impl IntoIterator<Item = &'h Header>,
575	) -> usize {
576	    headers.into_iter().map(|h| h.range.end - h.range.start).sum()
577	}
578

